# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN RAHATSIZLANMASI VE VEFATI (8 HAZİRAN 632)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Rahatsızlanma Süreci ve Son Günleri</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Veda Haccı dönüşü Safer ayında rahatsızlandı</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Eşlerinin izniyle Hz. Aişe\'nin (ra) odasında kaldı</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Namaz kıldırma görevini Hz. Ebû Bekir\'e (ra) verdi</text>\n  <text x="180" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Yanındaki son 7 dinarı ihtiyaç sahiplerine dağıttırdı</text>\n  <text x="180" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Mescid-i Nebevî\'de ashabıyla helalleşti</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#334155">İki Emanet: Kur\'an-ı Kerim ve Sünnet (Sekaleyn)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Dâr-ı Bekâya İrtihali ve Defnedilmesi</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Tarih: 12 Rebîülevvel 11 / 8 Haziran 632 Pazartesi</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Yaş: Kamerî takvime göre 63 yaşında</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Son Sözü: "Mea\'r-Refîkı\'l-A\'lâ" (En Yüce Dost\'a)</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Techiz ve Tekfin: Hz. Ali, Hz. Abbas, Üsame bin Zeyd</text>\n  <text x="520" y="200" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Kabri: Vefat ettiği Hz. Aişe\'nin odası (Ravza-i Mutahhara)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#166534">Cenaze namazını müminler gruplar hâlinde kıldı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SAHABİLERİN ÜZÜNTÜSÜ VE HZ. EBÛ BEKİR\'İN (RA) TARİHÎ KONUŞMASI</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Ashabın Derin Hüzün ve Şaşkınlığı</text>\n  <text x="180" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Medine derin bir sessizlik ve hüzne büründü</text>\n  <text x="180" y="122" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Sahabiler bu acı haberi kabullenmekte zorlandı</text>\n  <text x="180" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Hz. Ömer (ra) üzüntüsünden dolayı vefat haberine</text>\n  <text x="180" y="168" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">inanmak istemedi, Rabbine gittiğini düşündü</text>\n  <text x="180" y="196" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">• Hz. Fatıma (ra): "Babacığım, Rabbinin davetine</text>\n  <text x="180" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#854d0e">icabet etti, Firdevs cennetine kavuştu" dedi</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Hz. Ebû Bekir\'in (ra) Metaneti ve Hutbesi</text>\n  <text x="520" y="96" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Peygamberimizin alnından öpüp vedalaştı</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">"Kim Muhammed\'e (sav) tapıyorsa bilsin ki o vefat</text>\n  <text x="520" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">etmiştir; kim Allah\'a ibadet ediyorsa bilsin ki</text>\n  <text x="520" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">Allah Hayy\'dır (diridir), ölümsüzdür!"</text>\n  <text x="520" y="190" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Âl-i İmrân Suresi 144. Ayeti okudu</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" fill="#475569">Sahabiler hakikati kavrayıp sükûnete kavuştu</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN MEDİNE YILLARI — KRONOLOJİK ÖZET</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">1. Kuruluş ve Kardeşlik</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Hicret (622): Medine\'ye varış</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11" fill="#881337">• Mescid-i Nebevî ve Suffe inşası</text>\n  <text x="125" y="144" text-anchor="middle" font-size="11" fill="#881337">• Muâhât (Ensar-Muhacir kardeşliği)</text>\n  <text x="125" y="168" text-anchor="middle" font-size="11" fill="#881337">• Medine Sözleşmesi (Vatandaşlık)</text>\n  <text x="125" y="192" text-anchor="middle" font-size="11" fill="#881337">• Medine Pazarı\'nın kurulması</text>\n  <text x="125" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#9f1239">Toplumsal ve siyasi temeller atıldı</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">2. Savunma ve Barış</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Bedir Savaşı (624): İlk zafer</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#164e63">• Uhud Savaşı (625): Okçular Tepesi</text>\n  <text x="350" y="144" text-anchor="middle" font-size="11" fill="#164e63">• Hendek Savaşı (627): Selman-ı Farisî</text>\n  <text x="350" y="168" text-anchor="middle" font-size="11" fill="#164e63">• Hudeybiye Barışı (628): Feth-i Mübîn</text>\n  <text x="350" y="192" text-anchor="middle" font-size="11" fill="#164e63">• İslam\'a davet mektupları (628)</text>\n  <text x="350" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#155e75">Barış ortamında İslam hızla yayıldı</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">3. Fetih, Veda ve İrtihal</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">• Mekke\'nin Fethi (630): Genel af</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11" fill="#14532d">• Kâbe putlardan temizlendi</text>\n  <text x="575" y="144" text-anchor="middle" font-size="11" fill="#14532d">• Elçiler Yılı (Senetü\'l-Vüfûd - 631)</text>\n  <text x="575" y="168" text-anchor="middle" font-size="11" fill="#14532d">• Veda Haccı ve Veda Hutbesi (632)</text>\n  <text x="575" y="192" text-anchor="middle" font-size="11" fill="#14532d">• Vefatı: 8 Haziran 632 (Medine)</text>\n  <text x="575" y="220" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">Tebliğ görevi kemale erdi (Mâide 3)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
